--
-- Table structure for table `adapay_corp_member`
--

DROP TABLE IF EXISTS `adapay_corp_member`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `adapay_corp_member` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `app_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '应用app_id',
  `order_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '请求订单号',
  `member_id` bigint NOT NULL COMMENT 'member_id',
  `company_id` bigint NOT NULL COMMENT '公司id',
  `dealer_id` bigint DEFAULT '0' COMMENT '经销商id',
  `distributor_id` bigint DEFAULT '0' COMMENT '店铺id',
  `operator_id` int DEFAULT '0' COMMENT '操作者id',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '企业名称',
  `prov_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '省份编码',
  `area_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '地区编码',
  `social_credit_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '统一社会信用码',
  `social_credit_code_expires` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '统一社会信用证有效期',
  `business_scope` varchar(800) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '经营范围',
  `legal_person` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '法人姓名',
  `legal_cert_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '法人身份证号码',
  `legal_cert_id_expires` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '法人身份证有效期',
  `legal_mp` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '法人手机号',
  `address` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '企业地址',
  `zip_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '邮编',
  `telphone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '企业电话',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '企业邮箱',
  `attach_file` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '上传附件',
  `attach_file_name` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '附件文件名',
  `confirm_letter_file` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '经销商确认函附件',
  `confirm_letter_file_name` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '经销商确认函附件文件名',
  `bank_code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '银行代码，如果需要自动开结算账户，本字段必填',
  `bank_acct_type` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '银行账户类型：1-对公；2-对私，如果需要自动开结算账户，本字段必填',
  `card_no` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '银行卡号，如果需要自动开结算账户，本字段必填',
  `card_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '银行卡对应的户名，如果需要自动开结算账户，本字段必填；若银行账户类型是对公，必须与企业名称一致',
  `audit_state` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '审核状态，状态包括：A-待审核；B-审核失败；C-开户失败；D-开户成功但未创建结算账户；E-开户和创建结算账户成功',
  `audit_desc` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '审核结果描述',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '当前交易状态',
  `error_info` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '错误描述',
  `create_time` int NOT NULL COMMENT '创建时间',
  `update_time` int DEFAULT NULL COMMENT '更新时间',
