--
-- Table structure for table `adapay_settle_account`
--

DROP TABLE IF EXISTS `adapay_settle_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `adapay_settle_account` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `app_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '应用app_id',
  `settle_account_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '由 Adapay 生成的结算账户对象 id',
  `member_id` bigint NOT NULL COMMENT 'member_id',
  `company_id` bigint NOT NULL COMMENT '公司id',
  `channel` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'bank_account' COMMENT '目前仅支持：bank_account（银行卡）',
  `card_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '银行卡号，如果需要自动开结算账户，本字段必填',
  `card_name` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '银行卡对应的户名，如果需要自动开结算账户，本字段必填；若银行账户类型是对公，必须与企业名称一致',
  `cert_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '证件号',
  `cert_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '00' COMMENT '证件类型，仅支持：00-身份证',
  `tel_no` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '用户手机号',
  `bank_code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '银行编码，详见附录 银行代码，银行账户类型对公时，必填',
  `bank_name` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '开户银行名称',
  `bank_acct_type` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '银行账户类型：1-对公；2-对私，如果需要自动开结算账户，本字段必填',
  `prov_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '省份编码, 银行账户类型为对公时，必填',
  `area_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '地区编码, 银行账户类型为对公时，必填',
  `create_time` int NOT NULL COMMENT '创建时间',
  `update_time` int DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_member_id` (`member_id`),
  KEY `idx_company_id` (`company_id`),
  KEY `idx_settle_account_id` (`settle_account_id`),
  KEY `idx_card_id` (`card_id`(64)),
  KEY `idx_cert_id` (`cert_id`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='结算账户';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `adapay_settle_account`
--

LOCK TABLES `adapay_settle_account` WRITE;
/*!40000 ALTER TABLE `adapay_settle_account` DISABLE KEYS */;
/*!40000 ALTER TABLE `adapay_settle_account` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `adapay_sms_log`
--

DROP TABLE IF EXISTS `adapay_sms_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `adapay_sms_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `company_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公司id',
