INSERT INTO `aliyunsms_scene` VALUES (1,1,'短信验证码','verification_code','0','disabled','验证码：${验证码}，30分钟内有效，如非本人操作请忽略！','[{\"var_name\":\"code\",\"var_title\":\"\\u9a8c\\u8bc1\\u7801\",\"rule\":\"numberCaptcha\"}]',1785515114,1785515114),(2,1,'支付成功通知','trade_pay_success','1','disabled','您于${支付时间}成功支付${支付金额}元。','[{\"var_name\":\"pay_time\",\"var_title\":\"\\u652f\\u4ed8\\u65f6\\u95f4\",\"rule\":\"time\"},{\"var_name\":\"pay_money\",\"var_title\":\"\\u652f\\u4ed8\\u91d1\\u989d\",\"rule\":\"money\"}]',1785515114,1785515114),(3,1,'到店自提-发送提货码','order_pickup','1','disabled','您${订单号}的订单提货码是${提货码}，30分钟内有效，请勿泄漏。','[{\"var_name\":\"order_id\",\"var_title\":\"\\u8ba2\\u5355\\u53f7\",\"rule\":\"other_number2\"},{\"var_name\":\"pickup_code\",\"var_title\":\"\\u63d0\\u8d27\\u7801\",\"rule\":\"pick_up_code\"}]',1785515114,1785515114),(4,1,'助力成功通知','bargainFinish_notice','1','disabled','恭喜您，您的${商品名称}助力成功，支付金额：${支付金额}元，请于${结束时间}前完成支付！','[{\"var_name\":\"item_name\",\"var_title\":\"\\u5546\\u54c1\\u540d\\u79f0\",\"rule\":\"others\"},{\"var_name\":\"pay_money\",\"var_title\":\"\\u652f\\u4ed8\\u91d1\\u989d\",\"rule\":\"money\"},{\"var_name\":\"end_time\",\"var_title\":\"\\u7ed3\\u675f\\u65f6\\u95f4\",\"rule\":\"time\"}]',1785515114,1785515114),(5,1,'活动报名审核结果通知','registration_result_notice','1','disabled','您参与的${活动名称}活动，已经${审核结果}，请及时查看！','[{\"var_name\":\"activity_name\",\"var_title\":\"\\u6d3b\\u52a8\\u540d\\u79f0\",\"rule\":\"others\"},{\"var_name\":\"review_result\",\"var_title\":\"\\u5ba1\\u6838\\u7ed3\\u679c\",\"rule\":\"others\"}]',1785515114,1785515114),(6,1,'活动报名成功通知','registration_success_notice','1','disabled','您好！您参与的${活动名称}活动，已经报名成功，活动开始时间：${活动开始时间} 活动地点：${活动地点} 活动详细地址：${活动详细地址} 感谢您的参与让这次活动更加精彩。欢迎参会，顺祝时祺！','[{\"var_name\":\"activity_name\",\"var_title\":\"\\u6d3b\\u52a8\\u540d\\u79f0\",\"rule\":\"others\"},{\"var_name\":\"activity_start_time\",\"var_title\":\"\\u6d3b\\u52a8\\u5f00\\u59cb\\u65f6\\u95f4\",\"rule\":\"others\"},{\"var_name\":\"activity_place\",\"var_title\":\"\\u6d3b\\u52a8\\u5730\\u70b9\",\"rule\":\"others\"},{\"var_name\":\"activity_address\",\"var_title\":\"\\u6d3b\\u52a8\\u8be6\\u7ec6\\u5730\\u5740\",\"rule\":\"others\"}]',1785515114,1785515114),(7,1,'活动报名审核失败通知','registration_fail_notice','1','disabled','您好！您参与的${活动名称}活动，尚未登记成功。这可能由于以下原因：${拒绝原因} 请核对后尽快再次填报。顺祝时祺！','[{\"var_name\":\"activity_name\",\"var_title\":\"\\u6d3b\\u52a8\\u540d\\u79f0\",\"rule\":\"others\"},{\"var_name\":\"activity_refuse_reason\",\"var_title\":\"\\u62d2\\u7edd\\u539f\\u56e0\",\"rule\":\"others\"}]',1785515114,1785515114),(8,1,'ECShopX商户入驻-申请入驻成功通知','merchant_audit_success_notice','1','disabled','您申请的商户入驻已审批通过，请登录（商户入驻链接（H5）请手动替换）查看商户后台登录的账号和密码。',NULL,1785515114,1785515114),(9,1,'ECShopX商户入驻-申请入驻审批未通过通知','merchant_audit_fail_notice','1','disabled','您提交的商户入驻审批未通过，请及时登录（商户入驻链接（H5）请手动替换）查看。',NULL,1785515114,1785515114),(10,1,'ECShopX商户入驻-后台添加商户成功通知','merchant_enter_success_notice','1','disabled','商户入驻成功，请使用（商户后台登录地址请手动替换），登录账号为${手机号}，密码为${随机密码}登录商户后台。','[{\"var_name\":\"password\",\"var_title\":\"\\u968f\\u673a\\u5bc6\\u7801\",\"rule\":\"other_number2\"},{\"var_name\":\"phone\",\"var_title\":\"\\u624b\\u673a\\u53f7\",\"rule\":\"phone_number2\"}]',1785515114,1785515114),(11,1,'ECShopX商户后台登录密码重置成功通知','merchant_reset_password_notice','1','disabled','您的密码是${随机密码}，请勿泄漏。','[{\"var_name\":\"password\",\"var_title\":\"\\u968f\\u673a\\u5bc6\\u7801\",\"rule\":\"other_number2\"}]',1785515114,1785515114),(12,1,'Adapay分账-主商户开户审批结果通知','admin_account_approved','1','disabled','${商户名称}提交的Adapay分账开户申请${步骤}已审批完成，请及时查看。','[{\"var_name\":\"mer_name\",\"var_title\":\"\\u5546\\u6237\\u540d\\u79f0\",\"rule\":\"others\"},{\"var_name\":\"step\",\"var_title\":\"\\u6b65\\u9aa4\",\"rule\":\"others\"}]',1785515114,1785515114),(13,1,'Adapay分账-子商户开户成功通知','sub_account_approved','1','disabled','${商户名称}提交的开户申请已审批完成，请及时查看。','[{\"var_name\":\"mer_name\",\"var_title\":\"\\u5546\\u6237\\u540d\\u79f0\",\"rule\":\"others\"}]',1785515114,1785515114),(14,1,'Adapay分账-经销商后台登录密码重置','dealer_account_reset_pwd','1','disabled','${经销商名称}登录密码已重置，密码为:${随机密码}，请勿泄漏！','[{\"var_name\":\"dealer\",\"var_title\":\"\\u7ecf\\u9500\\u5546\\u540d\\u79f0\",\"rule\":\"others\"},{\"var_name\":\"password\",\"var_title\":\"\\u968f\\u673a\\u5bc6\\u7801\",\"rule\":\"other_number2\"}]',1785515114,1785515114),(15,1,'场景营销-会员生日','member_birthday','2','disabled','尊敬的会员：值此您生日之际，衷心祝您生日快乐！为感谢您对本店的支持，特此赠送您专属优惠券，请及时查收！',NULL,1785515114,1785515114),(16,1,'场景营销-入会周年','member_anniversary','2','disabled','历史上的今天，您成为了（品牌名称，请手动替换）会员。感谢您一路的支持，特此为您奉上会员专属优惠券，请及时查收！',NULL,1785515114,1785515114),(17,1,'场景营销-会员日','member_day','2','disabled','（会员日日期，请手动替换）是（品牌名称，请手动替换）会员日，特此为您奉上会员专属优惠券，请及时查看！到店更有其他惊喜',NULL,1785515114,1785515114),(18,1,'场景营销-普通会员升级','member_upgrade','2','disabled','恭喜您在（品牌名称，请手动替换）的会员升级成功，特此为您奉上会员专属优惠券，请及时查收！到店更有其他惊喜',NULL,1785515114,1785515114),(19,1,'场景营销-付费会员升级','member_vip_upgrade','2','disabled','恭喜您在（品牌名称，请手动替换）的会员升级成功，特此为您奉上会员专属优惠券，请及时查收！',NULL,1785515114,1785515114),(20,1,'向会员群发推广短信','sms_task','2','disabled',NULL,NULL,1785515114,1785515114);
