  `enable_agreement` tinyint(1) NOT NULL DEFAULT '0' COMMENT '开启购买协议',
  `date_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '有效期的类型, DATE_TYPE_FIX_TIME_RANGE:指定日期范围内, DATE_TYPE_FIX_TERM:固定天数后',
  `begin_date` int DEFAULT NULL COMMENT '有效期开始时间',
  `end_date` int DEFAULT NULL COMMENT '有效期结束时间',
  `fixed_term` int DEFAULT NULL COMMENT '有效期的有效天数',
  `brand_logo` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品牌图片',
  `is_point` tinyint(1) DEFAULT '0' COMMENT '是否积分兑换 true可以 false不可以',
  `point` int DEFAULT '0' COMMENT '积分个数',
  `distributor_id` int NOT NULL DEFAULT '0' COMMENT '店铺id,为0时表示该商品为商城商品，否则为店铺自有商品',
  `volume` double DEFAULT NULL COMMENT '商品体积',
  `item_source` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mall' COMMENT '商品来源:mall:主商城;distributor:店铺自有;openapi:开放接口;',
  `brand_id` int DEFAULT '0' COMMENT '品牌id',
  `tax_rate` int NOT NULL COMMENT '税率, 百分之～/100',
