  `profit_type` int DEFAULT '0' COMMENT '分润类型, 默认为0配置分润,1主类目分润,2商品指定分润(比例),3商品指定分润(金额)',
  `origincountry_id` bigint NOT NULL DEFAULT '0' COMMENT '产地国id',
  `taxstrategy_id` bigint NOT NULL DEFAULT '0' COMMENT '税费策略id',
  `taxation_num` int NOT NULL DEFAULT '0' COMMENT '计税单位份数',
  `profit_fee` int DEFAULT '0' COMMENT '分润金额,单位为分 冗余字段',
  `type` int NOT NULL DEFAULT '0' COMMENT '商品类型，0普通，1跨境商品，可扩展',
  `is_profit` tinyint(1) DEFAULT '0' COMMENT '是否支持分润',
