  `updated` int DEFAULT NULL,
  `is_gift` tinyint(1) DEFAULT '0' COMMENT '是否为赠品',
  `is_package` tinyint(1) DEFAULT '0' COMMENT '是否为打包产品',
  `tdk_content` longtext COLLATE utf8mb4_unicode_ci COMMENT 'tdk详情',
  `is_epidemic` int DEFAULT '0' COMMENT '是否为疫情需要登记的商品  1:是 0:否',
  `regions` longtext COLLATE utf8mb4_unicode_ci COMMENT '产地地区',
  `supplier_id` int NOT NULL DEFAULT '0' COMMENT '供应商id',
  `is_market` int NOT NULL DEFAULT '1' COMMENT '供应商控制商品是否可售，0不可售，1可售',
  `goods_bn` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编号',
