  `audit_date` int DEFAULT NULL COMMENT '商品审核时间',
  `is_medicine` smallint NOT NULL DEFAULT '0' COMMENT '是否为药品，0否 1是',
  `is_prescription` smallint NOT NULL DEFAULT '0' COMMENT '是否为处方药，0否 1是',
  `supplier_item_id` int NOT NULL DEFAULT '0' COMMENT '供应商商品id',
  `start_num` int DEFAULT '0' COMMENT '起订量',
  `delivery_time` int DEFAULT '0' COMMENT '发货时间，如2，表示2天发货',
  `is_taobao` int DEFAULT '0' COMMENT '是否淘宝商品',
  PRIMARY KEY (`item_id`),
