  KEY `ix_goods_id` (`goods_id`),
  KEY `ix_default_item_list` (`company_id`,`default_item_id`,`approve_status`,`item_type`,`item_category`),
  KEY `ix_item_bn` (`item_bn`),
  KEY `ix_is_medicine` (`is_medicine`),
  KEY `ix_is_prescription` (`is_prescription`),
  KEY `ix_supplier_item_id` (`supplier_item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商品表';
