  `cost_fee` int NOT NULL COMMENT '商品成本价，以分为单位',
  `shop_id` bigint DEFAULT '0' COMMENT '门店id',
  `act_id` bigint DEFAULT NULL COMMENT '营销活动ID，团购ID，社区拼团ID，秒杀活动ID等',
  `is_total_store` tinyint(1) DEFAULT '1' COMMENT '是否是总部库存(true:总部库存，false:店铺库存)',
  `distributor_id` bigint NOT NULL DEFAULT '0' COMMENT '分销商id',
  `item_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品名称',
  `item_unit` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品计量单位',
  `pic` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品图片',
  `num` int NOT NULL COMMENT '购买商品数量',
  `price` int NOT NULL COMMENT '单价，以分为单位',
  `market_price` int NOT NULL DEFAULT '0' COMMENT '原价，以分为单位',
  `total_fee` int NOT NULL COMMENT '订单金额，以分为单位',
  `rebate` int NOT NULL DEFAULT '0' COMMENT '单个分销金额，以分为单位',
