  `templates_id` int NOT NULL DEFAULT '0' COMMENT '运费模板id',
  `item_fee` int NOT NULL COMMENT '商品总金额，以分为单位',
  `member_discount` int NOT NULL COMMENT '会员折扣金额，以分为单位',
  `coupon_discount` int NOT NULL COMMENT '优惠券抵扣金额，以分为单位',
  `discount_fee` int NOT NULL DEFAULT '0' COMMENT '订单优惠金额，以分为单位',
  `discount_info` longtext COLLATE utf8mb4_unicode_ci COMMENT '订单优惠详情',
  `add_service_info` longtext COLLATE utf8mb4_unicode_ci COMMENT '订单商品附加信息',
  `order_item_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal' COMMENT '订单商品类型,normal:正常商品，gift: 赠品, plus_buy: 加价购商品',
  `coupon_discount_desc` longtext COLLATE utf8mb4_unicode_ci COMMENT '优惠券使用详情',
