  `is_rate` tinyint(1) DEFAULT '0' COMMENT '是否评价',
  `auto_close_aftersales_time` int DEFAULT NULL COMMENT '自动关闭售后时间',
  `create_time` int NOT NULL COMMENT '订单创建时间',
  `update_time` int DEFAULT NULL COMMENT '订单更新时间',
  `delivery_corp` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '快递公司',
  `delivery_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '快递单号',
  `delivery_img` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '快递发货凭证',
  `delivery_time` int DEFAULT NULL COMMENT '发货时间',
  `delivery_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '发货状态。可选值有 DONE—已发货;PENDING—待发货',
  `aftersales_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '售后状态。可选值有 WAIT_SELLER_AGREE 0 等待商家处理;WAIT_BUYER_RETURN_GOODS 1 商家接受申请，等待消费者回寄;WAIT_SELLER_CONFIRM_GOODS 2 消费者回寄，等待商家收货确认;SELLER_REFUSE_BUYER 3 售后驳回;SELLER_SEND_GOODS 4 卖家重新发货 换货完成;REFUND_SUCCESS 5 退款成功;REFUND_CLOSED 6 退款关闭;CLOSED 7 售后关闭',
  `refunded_fee` int NOT NULL DEFAULT '0' COMMENT '退款金额，以分为单位',
  `fee_type` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CNY' COMMENT '货币类型',
  `fee_rate` double NOT NULL DEFAULT '1' COMMENT '货币汇率',
  `fee_symbol` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '￥' COMMENT '货币符号',
  `item_point` int DEFAULT '0' COMMENT '商品积分',
  `point` int DEFAULT '0' COMMENT '商品总积分',
  `item_spec_desc` longtext COLLATE utf8mb4_unicode_ci COMMENT '商品规格描述',
  `volume` int DEFAULT '0' COMMENT '商品体积',
  `weight` double DEFAULT '0' COMMENT '商品重量',
  `type` int NOT NULL DEFAULT '0' COMMENT '订单类型，0普通订单,1跨境订单,....其他',
  `tax_rate` varchar(6) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '商品税率',
  `cross_border_tax` int NOT NULL DEFAULT '0' COMMENT '商品跨境税费',
  `origincountry_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '产地国名称',
  `origincountry_img_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '产地国国旗',
  `point_fee` int DEFAULT '0' COMMENT '积分抵扣时分摊的积分的金额，以分为单位',
  `is_logistics` tinyint(1) DEFAULT '0' COMMENT '门店缺货商品总部快递发货',
  `share_points` int DEFAULT '0' COMMENT '积分抵扣时分摊的积分值',
  `up_share_points` int DEFAULT '0' COMMENT '积分抵扣时分摊的积分升值数',
  `taxable_fee` int NOT NULL DEFAULT '0' COMMENT '计税总价，以分为单位',
  `delivery_item_num` int DEFAULT NULL COMMENT '发货单发货数量',
  `get_points` int DEFAULT '0' COMMENT '商品获取积分',
  `cancel_item_num` int DEFAULT NULL COMMENT '取消数量',
  `goods_bn` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品spu编码',
  `commission_fee` int NOT NULL DEFAULT '0' COMMENT '佣金(分)',
  `cost_price` int NOT NULL DEFAULT '0' COMMENT '原价价，以分为单位',
  `supplier_id` int NOT NULL DEFAULT '0' COMMENT '供应商id',
  `goods_id` bigint NOT NULL COMMENT '产品id',
  `is_prescription` int NOT NULL DEFAULT '0' COMMENT '是否为处方药商品,0否 1是',
  `is_invoice` int NOT NULL DEFAULT '0' COMMENT '是否开票,0否 1已开票 2开票中 3红冲',
  PRIMARY KEY (`id`),
  KEY `idx_company_order_id` (`company_id`,`order_id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='实体订单明细表';
