  `brand_id` int DEFAULT '0' COMMENT '品牌id',
  `tax_rate` int NOT NULL COMMENT '税率, 百分之～/100',
  `crossborder_tax_rate` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跨境税率，百分比，小数点2位',
  `profit_type` int DEFAULT '0' COMMENT '分润类型, 默认为0配置分润,1主类目分润,2商品指定分润(比例),3商品指定分润(金额)',
  `origincountry_id` bigint NOT NULL DEFAULT '0' COMMENT '产地国id',
