  KEY `ix_is_medicine` (`is_medicine`),
  KEY `ix_is_prescription` (`is_prescription`),
  KEY `ix_supplier_id` (`supplier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商品表';
