  `audit_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '微信返回的审核id',
  `resource_id` bigint DEFAULT NULL COMMENT '资源包id',
  `expired_at` bigint DEFAULT NULL COMMENT '过期时间',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否是默认门店',
  `country` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '非中国国家名称',
  `city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '非中国门店所在城市',
  `is_domestic` smallint DEFAULT '1' COMMENT '是否是中国国内门店 1:国内(包含港澳台),2:非国内',
  `is_direct_store` smallint DEFAULT '1' COMMENT '是否为直营店 1:直营店,2:非直营店',
  `is_open` tinyint(1) DEFAULT '1' COMMENT '是否开启 1:开启,0:关闭',
  `created` int NOT NULL,
  `updated` int NOT NULL,
  PRIMARY KEY (`wx_shop_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='微信门店表';
